pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address recipient = address(0x1);
        vm.deal(address(this), 1 ether);
        // Fund the contract
        payable(address(c)).transfer(1 ether);
        // Now call withdrawAll as owner
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: require(msg.sender == owner) reverts if not owner
        // Since we are the owner (deployed as address(this)), it should succeed
        assertTrue(ok);
    }
}

