pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        address alice = address(0x1234);
        vm.deal(address(c), 1 ether);
        // A non-owner (alice) attempts to withdraw
        vm.prank(alice);
        c.withdrawAll(alice);
        // In the reference, the require reverts, so the balance stays 1 ether.
        // In the buggy version, no revert, so the balance becomes 0.
        assertTrue(address(c).balance == 1 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1e18);
        // Simulate a non-owner calling withdrawAll with a recipient that can receive ether
        address nonOwner = address(0x1234);
        address recipient = address(0x4567);
        vm.deal(nonOwner, 0); // no ether needed for the call
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call, the reference contract reverts (non-owner), so balance should remain 1e18
        // The buggy contract does not revert and sends 1e18 to recipient, making balance 0
        assertTrue(ok == false && address(c).balance == 1e18);
    }
}

