// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Send 1 ether to the contract via fallback
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "send failed");
        // Now call withdrawAll with recipient = address(this)
        c.withdrawAll(address(this));
        // The reference transfers all balance -> 0; the bug transfers 0 -> balance stays 1 ether
        assertTrue(address(c).balance < 1 ether, "balance should be zero after withdrawAll");
    }
}

